    /**
     * Method to retrieve the Forecast via ForecastFetchOneSummary
     * @param 	summary ForecastFetchOneSummary 
     * @return 	ForecastFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Forecast getForecast( ForecastFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ForecastFetchOneSummary arg cannot be null" );
    	
    	Forecast entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Forecast
        	// --------------------------------------
        	CompletableFuture<Forecast> futureEntity = queryGateway.query(new FindForecastQuery( new LoadForecastFilter( summary.getForecastId() ) ), ResponseTypes.instanceOf(Forecast.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Forecast with id " + summary.getForecastId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


